void main()=>runApp(const PaliaShare());
class PaliaShare extends StatelessWidget{const PaliaShare({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Palia Share',theme:ThemeData(useMaterial3:true,colorSchemeSeed:mint,scaffoldBackgroundColor:Colors.white),home:const Home());}
class Home extends StatefulWidget{const Home({super.key});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{int tab=0;final history=<String>[];@override Widget build(BuildContext c){final pages=[HomePage(onHistory:(x)=>setState(()=>history.insert(0,x))),const Transfers(),const Devices(),History(items:history),const Settings()];return Scaffold(body:SafeArea(child:pages[tab]),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home),label:'Home'),NavigationDestination(icon:Icon(Icons.swap_horiz),label:'Transfers'),NavigationDestination(icon:Icon(Icons.devices_other),label:'Devices'),NavigationDestination(icon:Icon(Icons.history),label:'History'),NavigationDestination(icon:Icon(Icons.settings_outlined),label:'Settings')]));}}
class HomePage extends StatelessWidget{final ValueChanged<String> onHistory;const HomePage({super.key,required this.onHistory});@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(20),children:[Row(children:[Container(width:48,height:48,padding:8,decoration:BoxDecoration(color:mint.withOpacity(.1),borderRadius:BorderRadius.circular(15)),child:SvgPicture.asset('assets/palia_share_logo.svg')),const SizedBox(width:12),const Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Palia Share',style:TextStyle(fontSize:24,fontWeight:FontWeight.w800)),Text('Fast. Simple. Secure.',style:TextStyle(color:Colors.black54))])),const Icon(Icons.account_circle_outlined,size:32)]),const SizedBox(height:22),Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xFFEFFFFA),Color(0xFFF8FFFC)]),borderRadius:BorderRadius.circular(28)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Share files at lightning speed',style:TextStyle(fontSize:24,fontWeight:FontWeight.w800)),const SizedBox(height:8),const Text('Transfer photos, videos, apps and documents directly between nearby Android phones.',style:TextStyle(color:Colors.black54,height:1.4)),const SizedBox(height:18),Row(children:[Expanded(child:FilledButton.icon(onPressed:()=>pick(c,onHistory),icon:const Icon(Icons.send_rounded),label:const Text('Send Files'))),const SizedBox(width:10),Expanded(child:OutlinedButton.icon(onPressed:()=>receive(c,onHistory),icon:const Icon(Icons.download_rounded),label:const Text('Receive')))])])),const SizedBox(height:24),const Text('Quick Share',style:TextStyle(fontSize:18,fontWeight:FontWeight.w800)),const SizedBox(height:12),Row(children:[q(Icons.photo_library_outlined,'Photos'),q(Icons.videocam_outlined,'Videos'),q(Icons.android,'Apps'),q(Icons.folder_outlined,'Files')]),const SizedBox(height:24),Container(padding:const EdgeInsets.all(18),decoration:BoxDecoration(borderRadius:BorderRadius.circular(22),border:Border.all(color:mint.withOpacity(.18))),child:const Row(children:[CircleAvatar(backgroundColor:Color(0xFFE8FBF5),child:Icon(Icons.wifi_tethering,color:mint)),SizedBox(width:14),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Ready to connect',style:TextStyle(fontWeight:FontWeight.w700)),Text('Choose Send or Receive to start.',style:TextStyle(color:Colors.black54))]))])),const SizedBox(height:20),InkWell(onTap:openHub,borderRadius:BorderRadius.circular(22),child:Container(padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:Color(0xFFF3FBF8),borderRadius:BorderRadius.circular(22)),child:const Row(children:[Icon(Icons.rocket_launch_outlined,color:mint,size:30),SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('More Apps & Updates',style:TextStyle(fontWeight:FontWeight.w800,fontSize:16)),SizedBox(height:4),Text('Discover apps, games and updates on PaliaAPK HUB.',style:TextStyle(color:Colors.black54))])),Icon(Icons.arrow_forward_ios,size:16,color:mint)]))) ]);}
Widget q(IconData i,String t)=>Expanded(child:Column(children:[Container(width:56,height:56,decoration:BoxDecoration(color:const Color(0xFFF1FBF8),borderRadius:BorderRadius.circular(17)),child:Icon(i,color:mint)),const SizedBox(height:6),Text(t,style:const TextStyle(fontSize:12))]));}
Future<void> pick(BuildContext c,ValueChanged<String> done)async{final r=await FilePicker.platform.pickFiles(allowMultiple:true);if(r==null)return;if(c.mounted)Navigator.push(c,MaterialPageRoute(builder:(_)=>SendPage(files:r.files,onDone:done)));}
Future<void> receive(BuildContext c,ValueChanged<String> done)async{if(c.mounted)showModalBottomSheet(context:c,isScrollControlled:true,builder:(_)=>ReceiveSheet(onDone:done));}
Future<void> openHub()async{final u=Uri.parse(hub);if(await canLaunchUrl(u))launchUrl(u,mode:LaunchMode.externalApplication);}
class SendPage extends StatefulWidget{final List<PlatformFile> files;final ValueChanged<String> onDone;const SendPage({super.key,required this.files,required this.onDone});@override State<SendPage> createState()=>_SendState();}
class _SendState extends State<SendPage>{final ip=TextEditingController();double p=0;String msg='Enter the receiver IP shown on their Receive screen.';bool busy=false;Future<void> send()async{if(ip.text.trim().isEmpty)return;setState(()=>busy=true);try{for(int i=0;i<widget.files.length;i++){final f=widget.files[i];if(f.path==null)continue;final file=File(f.path!);final req=http.StreamedRequest('PUT',Uri.parse('http://${ip.text.trim()}:8765/upload'));req.headers['x-file-name']=Uri.encodeComponent(f.name);req.headers['content-type']='application/octet-stream';req.contentLength=await file.length();file.openRead().listen(req.sink.add,onDone:req.sink.close,onError:req.sink.addError);final res=await req.send();if(res.statusCode!=200)throw Exception('HTTP ${res.statusCode}');setState(()=>p=(i+1)/widget.files.length);}setState(()=>msg='Transfer complete');widget.onDone('${widget.files.length} file(s) sent');}catch(e){setState(()=>msg='Transfer failed: $e');}finally{setState(()=>busy=false);}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Send Files')),body:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${widget.files.length} file(s) selected',style:const TextStyle(fontSize:20,fontWeight:FontWeight.w800)),const SizedBox(height:18),TextField(controller:ip,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Receiver IP address',hintText:'192.168.1.10',border:OutlineInputBorder())),const SizedBox(height:14),Text(msg),const SizedBox(height:18),LinearProgressIndicator(value:busy?p:null,minHeight:8,borderRadius:BorderRadius.circular(8)),const Spacer(),SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:busy?null:send,icon:const Icon(Icons.send),label:const Padding(padding:EdgeInsets.all(14),child:Text('Start Transfer'))))]));}
class ReceiveSheet extends StatefulWidget{final ValueChanged<String> onDone;const ReceiveSheet({super.key,required this.onDone});@override State<ReceiveSheet> createState()=>_ReceiveState();}
class _ReceiveState extends State<ReceiveSheet>{HttpServer?server;String ip='Finding...';String msg='Starting receiver…';@override void initState(){super.initState();start();}Future<void> start()async{try{server=await HttpServer.bind(InternetAddress.anyIPv4,8765);final list=await NetworkInterface.list(type:InternetAddressType.IPv4,includeLoopback:false);for(final n in list){for(final a in n.addresses){if(!a.address.startsWith('127.'))ip=a.address;}}setState(()=>msg='Ready — enter this IP on the sender.');await for(final r in server!){if(r.method=='PUT'&&r.uri.path=='/upload'){final name=Uri.decodeComponent(r.headers.value('x-file-name')??'received.bin');final d=await getApplicationDocumentsDirectory();final f=File('${d.path}/$name');await r.pipe(f.openWrite());r.response.statusCode=200;await r.response.close();widget.onDone(name);}else{r.response.statusCode=404;await r.response.close();}}}catch(e){if(mounted)setState(()=>msg='Receiver error: $e');}}@override void dispose(){server?.close(force:true);super.dispose();}@override Widget build(BuildContext c)=>Padding(padding:const EdgeInsets.fromLTRB(24,18,24,30),child:Column(mainAxisSize:MainAxisSize.min,children:[const Text('Receive Files',style:TextStyle(fontSize:22,fontWeight:FontWeight.w800)),const SizedBox(height:10),Text(msg,textAlign:TextAlign.center),const SizedBox(height:16),if(ip!='Finding...')QrImageView(data:'palia-share://$ip:8765',size:190),const SizedBox(height:10),Text(ip,style:const TextStyle(fontSize:24,fontWeight:FontWeight.w800)),const SizedBox(height:8),const Text('Both phones should be on the same local Wi-Fi network.',textAlign:TextAlign.center),const SizedBox(height:12),OutlinedButton(onPressed:()=>Navigator.pop(c),child:const Text('Done'))]));}
class Transfers extends StatelessWidget{const Transfers({super.key});@override Widget build(BuildContext c)=>const Center(child:Text('Transfers',style:TextStyle(fontSize:28,fontWeight:FontWeight.w800)));}
class Devices extends StatelessWidget{const Devices({super.key});@override Widget build(BuildContext c)=>const Center(child:Text('Nearby Devices',style:TextStyle(fontSize:28,fontWeight:FontWeight.w800)));}
class History extends StatelessWidget{final List<String>items;const History({super.key,required this.items});@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(20),children:[const Text('Transfer History',style:TextStyle(fontSize:26,fontWeight:FontWeight.w800)),const SizedBox(height:18),if(items.isEmpty)const Text('No transfers yet.',style:TextStyle(color:Colors.black54)),...items.map((x)=>ListTile(leading:const Icon(Icons.check_circle,color:mint),title:Text(x))) ]);}
class Settings extends StatelessWidget{const Settings({super.key});@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(20),children:[const Text('Settings',style:TextStyle(fontSize:28,fontWeight:FontWeight.w800)),const SizedBox(height:18),ListTile(leading:const Icon(Icons.notifications_none),title:const Text('Notifications'),subtitle:const Text('Manage Palia Share notifications in Android Settings'),onTap:()=>showDialog(context:c,builder:(_)=>const AlertDialog(title:Text('Notifications'),content:Text('Enable Palia Share notifications in Android Settings to receive update alerts.')))),ListTile(leading:const Icon(Icons.system_update_alt),title:const Text('Check for Updates'),subtitle:const Text('Open PaliaAPK HUB'),onTap:openHub),ListTile(leading:const Icon(Icons.public),title:const Text('PaliaAPK HUB'),subtitle:const Text(hub),onTap:openHub),const Divider(),const ListTile(title:Text('About Palia Share'),subtitle:Text('Fast. Simple. Secure.\nDeveloper by Shanpalia'))]);}
